135	func marshalDispatchPromptPayload(dispatch *Dispatch, voice string) (string, error) {
136		payload := dispatchPromptPayload{
137			Title:        summarizeLocalDispatchTitle(dispatch.CoveredRepos),
138			CoveredRepos: append([]string(nil), dispatch.CoveredRepos...),
139			Branches:     dispatchBranches(dispatch),
140			Voice:        sanitizeDispatchVoice(ResolveVoice(voice).Text),
141			Window: dispatchPromptWindow{
142				NormalizedSince:          formatDispatchTime(dispatch.Window.NormalizedSince),
143				NormalizedUntil:          formatDispatchTime(dispatch.Window.NormalizedUntil),
144				FirstCheckpointCreatedAt: formatOptionalDispatchTime(dispatch.Window.FirstCheckpointAt),
145				LastCheckpointCreatedAt:  formatOptionalDispatchTime(dispatch.Window.LastCheckpointAt),
146			},
147			Repos: make([]dispatchPromptRepo, 0, len(dispatch.Repos)),
148		}
149		if payload.Voice == "" {
150			payload.Voice = "neutral"
151		}
152	
153		for _, repo := range dispatch.Repos {
154			outRepo := dispatchPromptRepo{
155				FullName: repo.FullName,
156				Sections: make([]dispatchPromptSection, 0, len(repo.Sections)),
157			}
158			for _, section := range repo.Sections {
159				outSection := dispatchPromptSection{
160					Label:   section.Label,
161					Bullets: make([]dispatchPromptBullet, 0, len(section.Bullets)),
162				}
163				for _, bullet := range section.Bullets {
164					outSection.Bullets = append(outSection.Bullets, dispatchPromptBullet{
165						CheckpointID: bullet.CheckpointID,
166						Text:         bullet.Text,
167						Source:       bullet.Source,
168						Branch:       bullet.Branch,
169						CreatedAt:    formatDispatchTime(bullet.CreatedAt),
170						Labels:       append([]string(nil), bullet.Labels...),
171					})
172				}
173				outRepo.Sections = append(outRepo.Sections, outSection)
174			}
175			payload.Repos = append(payload.Repos, outRepo)
176		}
177	
178		var buf bytes.Buffer
179		enc := json.NewEncoder(&buf)
180		enc.SetEscapeHTML(false)
181		enc.SetIndent("", "  ")
182		if err := enc.Encode(payload); err != nil {
183			return "", err
184		}
185		return strings.TrimSpace(buf.String()), nil
186	}
