210	func summarizeLocalDispatchTitle(coveredRepos []string) string {
211		switch len(coveredRepos) {
212		case 1:
213			return "Dispatch for " + coveredRepos[0]
214		default:
215			return "Engineering Dispatch"
216		}
217	}
