157	func dispatchStatusDetails(opts dispatchpkg.Options) []string {
158		scope := "Scope: current repo"
159		switch {
160		case strings.TrimSpace(opts.Org) != "":
161			scope = "Scope: org/" + strings.TrimSpace(opts.Org)
162		case len(opts.RepoPaths) > 0:
163			scope = "Scope: " + strings.Join(opts.RepoPaths, ", ")
164		}
165	
166		branches := "Branches: current branch"
167		if opts.AllBranches {
168			branches = "Branches: all"
169		} else if opts.Mode == dispatchpkg.ModeLocal {
170			branches = "Branches: current branch"
171		} else if len(opts.Branches) > 0 {
172			branches = "Branches: " + strings.Join(opts.Branches, ", ")
173		} else if strings.TrimSpace(opts.Org) != "" || len(opts.RepoPaths) > 0 {
174			branches = "Branches: default branches"
175		}
176	
177		window := "Window: " + strings.TrimSpace(opts.Since)
178		if strings.TrimSpace(opts.Until) != "" {
179			window += " → " + strings.TrimSpace(opts.Until)
180		}
181	
182		return []string{scope, branches, window}
183	}
