216		cardWidth := min(max(m.width-8, 44), 76)
217	
218		lines := []string{
219			m.styles.spinner.Render(m.spinner.View()) + " " + m.styles.title.Render(m.title),
220			m.styles.subtitle.Render(m.subtitle),
221			"",
222		}
223		for _, detail := range m.details {
224			lines = append(lines, m.styles.detail.Render(detail))
225		}
226		lines = append(lines, "", m.styles.footer.Render(m.footer))
227	
228		return m.styles.card.Width(cardWidth).Render(strings.Join(lines, "\n"))
229	}
230	
231	func (m dispatchStatusModel) runDispatch() tea.Cmd {
232		return func() tea.Msg {
233			markdown, err := m.run(m.ctx)
234			return dispatchRenderResult{markdown: markdown, err: err}
235		}
236	}
