126	func (c *CloudClient) doJSON(ctx context.Context, method, path string, reqBody, out any) error {
127		var body io.Reader
128		if reqBody != nil {
129			data, err := json.Marshal(reqBody)
130			if err != nil {
131				return fmt.Errorf("marshal request body: %w", err)
132			}
133			body = bytes.NewReader(data)
134		}
135	
136		req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
137		if err != nil {
138			return fmt.Errorf("create request: %w", err)
139		}
140		req.Header.Set("Accept", "application/json")
141		if reqBody != nil {
142			req.Header.Set("Content-Type", "application/json")
143		}
144		if c.token != "" {
145			req.Header.Set("Authorization", "Bearer "+c.token)
146		}
147	
148		resp, err := c.http.Do(req)
149		if err != nil {
150			return fmt.Errorf("%s %s: %w", method, path, err)
151		}
152		defer resp.Body.Close()
153	
154		if resp.StatusCode == http.StatusUnauthorized {
155			return errors.New("dispatch requires login — run `entire login`")
156		}
157		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
158			body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
159			trimmed := strings.TrimSpace(string(body))
160			if trimmed == "" {
161				return fmt.Errorf("%s %s: unexpected status %d", method, path, resp.StatusCode)
162			}
163			return fmt.Errorf("%s %s: unexpected status %d: %s", method, path, resp.StatusCode, trimmed)
164		}
165		if out == nil {
166			return nil
167		}
168		if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
169			return fmt.Errorf("decode response: %w", err)
170		}
171		return nil
172	}
