13	func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
14		token, err := lookupCurrentToken()
15		if err != nil {
16			return nil, fmt.Errorf("reading credentials: %w", err)
17		}
18		if token == "" {
19			return nil, fmt.Errorf("dispatch requires login — run `entire login`")
20		}
21	
22		now := nowUTC()
23		sinceInput := strings.TrimSpace(opts.Since)
24		if sinceInput == "" {
25			sinceInput = "7d"
26		}
27		since, err := ParseSinceAtNow(sinceInput, now)
28		if err != nil {
29			return nil, err
30		}
31		until, err := ParseUntilAtNow(opts.Until, now)
32		if err != nil {
33			return nil, err
34		}
35		if !since.Before(until) {
36			return nil, fmt.Errorf("--since must be before --until")
37		}
38	
39		var repoScope any
40		repoFullNames := append([]string(nil), opts.RepoPaths...)
41		if opts.Org == "" && len(repoFullNames) == 0 {
42			repoRoot, err := paths.WorktreeRoot(ctx)
43			if err != nil {
44				return nil, fmt.Errorf("not in a git repository: %w", err)
45			}
46			repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
47			if err != nil {
48				return nil, fmt.Errorf("open repository: %w", err)
49			}
50			repoFullName, err := resolveRepoFullName(repo)
51			if err != nil {
52				return nil, err
53			}
54			repoScope = repoFullName
55		} else if len(repoFullNames) == 1 {
56			repoScope = repoFullNames[0]
57		} else if len(repoFullNames) > 1 {
58			repoScope = repoFullNames
59		}
60	
61		branches := any(opts.Branches)
62		if opts.AllBranches {
63			branches = "all"
64		}
