38	// bearerTransport is an http.RoundTripper that injects the Authorization header.
39	type bearerTransport struct {
40		token string
41		base  http.RoundTripper
42	}
43	
44	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
45		// Clone the request to avoid mutating the caller's request.
46		r := req.Clone(req.Context())
47		r.Header.Set("Authorization", "Bearer "+t.token)
48		r.Header.Set("User-Agent", userAgent)
49		if r.Header.Get("Accept") == "" {
50			r.Header.Set("Accept", "application/json")
51		}
52		resp, err := t.base.RoundTrip(r)
53		if err != nil {
54			return nil, fmt.Errorf("round trip: %w", err)
55		}
56		return resp, nil
57	}
