65	func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
66		var reader io.Reader
67		if body != nil {
68			data, err := json.Marshal(body)
69			if err != nil {
70				return nil, fmt.Errorf("marshal request body: %w", err)
71			}
72			reader = bytes.NewReader(data)
73		}
74		return c.do(ctx, http.MethodPost, path, reader)
75	}
