108	func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
109		endpoint, err := ResolveURLFromBase(c.baseURL, path)
110		if err != nil {
111			return nil, fmt.Errorf("resolve URL %s: %w", path, err)
112		}
113	
114		req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
115		if err != nil {
116			return nil, fmt.Errorf("create request: %w", err)
117		}
118	
119		if body != nil {
120			req.Header.Set("Content-Type", "application/json")
121		}
122	
123		resp, err := c.httpClient.Do(req)
124		if err != nil {
