130	// DecodeJSON reads the response body and decodes it into dest.
131	// It limits the body size to protect against unbounded reads.
132	// The caller is responsible for closing resp.Body.
133	func DecodeJSON(resp *http.Response, dest any) error {
134		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
135		if err != nil {
136			return fmt.Errorf("read response body: %w", err)
137		}
138	
139		if err := json.Unmarshal(body, dest); err != nil {
140			return fmt.Errorf("decode JSON response: %w", err)
141		}
142	
143		return nil
144	}
