61				candidates, err := enumerateRepoCandidates(groupCtx, repoRoot, opts, normalizedSince, normalizedUntil)
62				if err != nil {
63					return err
64				}
65				candidatesMu.Lock()
66				allCandidates = append(allCandidates, candidates...)
