72			return nil, err
73		}
74	
75		fallback := applyFallbackChain(allCandidates)
76		dispatch := &Dispatch{
77			CoveredRepos: coveredRepos(allCandidates),
78			Repos:        groupBulletsByRepo(fallback.Used),
79			Totals:       computeTotals(allCandidates, fallback.Used),
80			Warnings:     fallback.Warnings,
81			Window: Window{
82				NormalizedSince:   normalizedSince,
83				NormalizedUntil:   normalizedUntil,
84				FirstCheckpointAt: firstAt(fallback.Used),
85				LastCheckpointAt:  lastAt(fallback.Used),
86			},
