218	func reachableCheckpointIDsOnHEAD(ctx context.Context, repoRoot string) (map[string]struct{}, error) {
219		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "HEAD", "--format=%B%x00")
220		output, err := cmd.Output()
221		if err != nil {
222			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
223		}
224	
225		reachable := make(map[string]struct{})
226		for _, message := range strings.Split(string(output), "\x00") {
227			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
228				reachable[checkpointID.String()] = struct{}{}
229			}
230		}
231		return reachable, nil
232	}
