250	func currentBranchName(repo *git.Repository) (string, error) {
251		head, err := repo.Head()
252		if err != nil {
253			return "", fmt.Errorf("get HEAD: %w", err)
254		}
255		if !head.Name().IsBranch() {
256			return "", errors.New("not on a branch (detached HEAD)")
257		}
258		return head.Name().Short(), nil
259	}
