274	func coveredRepos(candidates []candidate) []string {
275		if len(candidates) == 0 {
276			return nil
277		}
278	
279		repoSet := make(map[string]struct{}, len(candidates))
280		for _, candidate := range candidates {
281			if candidate.RepoFullName == "" {
282				continue
283			}
284			repoSet[candidate.RepoFullName] = struct{}{}
285		}
286	
287		repos := make([]string, 0, len(repoSet))
288		for repoFullName := range repoSet {
289			repos = append(repos, repoFullName)
