295	func groupBulletsByRepo(used []repoBullet) []RepoGroup {
296		repoMap := make(map[string]map[string][]Bullet)
297		for _, item := range used {
298			if _, ok := repoMap[item.RepoFullName]; !ok {
299				repoMap[item.RepoFullName] = make(map[string][]Bullet)
300			}
301			label := "Updates"
302			if len(item.Bullet.Labels) > 0 && strings.TrimSpace(item.Bullet.Labels[0]) != "" {
303				label = item.Bullet.Labels[0]
304			}
305			repoMap[item.RepoFullName][label] = append(repoMap[item.RepoFullName][label], item.Bullet)
306		}
307	
308		repoNames := make([]string, 0, len(repoMap))
309		for repoName := range repoMap {
310			repoNames = append(repoNames, repoName)
311		}
312		sort.Strings(repoNames)
313	
314		out := make([]RepoGroup, 0, len(repoNames))
315		for _, repoName := range repoNames {
316			sectionMap := repoMap[repoName]
317			labels := make([]string, 0, len(sectionMap))
318			for label := range sectionMap {
319				labels = append(labels, label)
320			}
321			sort.Strings(labels)
322	
323			sections := make([]Section, 0, len(labels))
324			for _, label := range labels {
325				sections = append(sections, Section{
326					Label:   label,
327					Bullets: sectionMap[label],
328				})
329			}
330			out = append(out, RepoGroup{FullName: repoName, Sections: sections})
331		}
332	
333		return out
334	}
