336	func computeTotals(candidates []candidate, used []repoBullet) Totals {
337		branches := make(map[string]struct{})
338		filesTouched := make(map[string]struct{})
339		for _, candidate := range candidates {
340			if candidate.Branch != "" {
341				branches[candidate.Branch] = struct{}{}
342			}
343			for _, file := range candidate.FilesTouched {
344				filesTouched[file] = struct{}{}
345			}
346		}
347	
348		return Totals{
349			Checkpoints:         len(candidates),
350			UsedCheckpointCount: len(used),
351			Branches:            len(branches),
352			FilesTouched:        len(filesTouched),
353		}
354	}
