356	func firstAt(used []repoBullet) time.Time {
357		var first time.Time
358		for _, item := range used {
359			if item.Bullet.CreatedAt.IsZero() {
360				continue
361			}
362			if first.IsZero() || item.Bullet.CreatedAt.Before(first) {
363				first = item.Bullet.CreatedAt
364			}
365		}
366		return first
367	}
